20:export class People {
21:  private readonly session = inject(Session);
22:  private readonly document = inject(DOCUMENT);
23:  private readonly api = inject(PeopleApi);
24:  private readonly claimsApi = inject(ClaimsApi);
25:  private readonly ratesApi = inject(RatesApi);
26:  private readonly periodsApi = inject(PeriodsApi);
27:  private readonly floor = inject(SheetFloor);
28:  private readonly terms = inject(SheetTerms);
29:  private readonly latePct = inject(SheetLatePct);
30:  private readonly policyDate = inject(SheetPolicyDate);
31:  /** What a late charge goes by: the sheet's today, terms and late percent; and the policy date rounding goes
32:   * by. */
33:  private readonly late = computed<Lateness>(() => ({
34:    today: this.session.today(),
35:    terms: this.terms.value(),
36:    latePct: this.latePct.value(),
37:    policyDate: this.policyDate.value() ?? this.session.today(),
38:  }));
39:
40:  protected readonly grades: Grade[] = ['A', 'B', 'C'];
41:  protected readonly people = signal<Person[]>([]);
42:  /** Whether retired people are listed; off when the screen opens, and kept as it is by loading a sheet. */
43:  protected readonly showRetired = signal(false);
44:  /** The people listed: everyone, or only those not retired unless retired people are shown. Totals count
45:   * everyone either way. */
46:  protected readonly shownPeople = computed(() =>
47:    this.showRetired() ? this.people() : this.people().filter((p) => !p.retiredFrom),
48:  );
49:  /** The sheet's claims, newest first. */
50:  protected readonly claims = signal<Claim[]>([]);
51:  private readonly claimsByPerson = computed(() => {
52:    const by = new Map<number, Claim[]>();
53:    for (const c of this.claims()) by.set(c.personId, [...(by.get(c.personId) ?? []), c]);
54:    return by;
55:  });
56:  /** The ids of the people on hold, whose OPEN claims count in no total. */
57:  private readonly heldIds = computed(() => new Set(this.people().filter((p) => p.held).map((p) => p.id)));
58:  protected readonly claimedTotal = computed(() =>
59:    sumAmounts(this.claims().filter((c) => this.countsLive(c)).map((c) => c.amount)),
60:  );
61:  /** The sheet's rates. */
62:  protected readonly rates = signal<Rate[]>([]);
63:  /** The rate each grade with one has in force on the sheet's today. */
64:  protected readonly rateByGrade = computed(() => {
65:    const today = this.session.today() ?? '';
66:    const by = new Map<Grade, string>();
67:    for (const g of this.grades) {
68:      const rate = rateOn(this.rates(), g, today);
69:      if (rate !== undefined) by.set(g, rate);
70:    }
71:    return by;
72:  });
73:
74:  /** The sheet's periods by from-date. */
75:  protected readonly periods = signal<Period[]>([]);
76:  /** Each period's due-total, by id: the sum of the dues of the claims that count dated in it (n/a ones
77:   * skipped), 0.00 with none; a closed period's is the one fixed when it closed. */
78:  protected readonly periodDueTotals = computed(() => {
79:    const byId = new Map(this.people().map((p) => [p.id, p]));
80:    const dues = new Map<number, string[]>();
81:    for (const c of this.claims().filter((c) => this.countsLive(c))) {
82:      const period = periodOf(this.periods(), c.date);
83:      const person = byId.get(c.personId);
84:      if (!period || !person) continue;
85:      const due = this.claimDue(c, person);
86:      if (due !== NO_RATE) dues.set(period.id, [...(dues.get(period.id) ?? []), due]);
87:    }
88:    return new Map(this.periods().map((p) => [p.id, p.closedTotal ?? sumAmounts(dues.get(p.id) ?? [])]));
89:  });
90:
91:  protected readonly dueTotal = computed(() =>
92:    sumAmounts(this.people().map((p) => this.personDueTotal(p)).filter((d) => d !== NO_RATE)),
93:  );
94:  /** Per grade, the people not retired who have it on the sheet's today and their due-totals added up (n/a
95:   * ones skipped). */
96:  protected readonly gradeSummary = computed<GradeSummary[]>(() =>
97:    this.grades.map((grade) => {
98:      const on = this.people().filter((p) => !p.retiredFrom && this.gradeToday(p) === grade);
99:      const dueTotal = sumAmounts(on.map((p) => this.personDueTotal(p)).filter((d) => d !== NO_RATE));
100:      return { grade, count: on.length, dueTotal };
101:    }),
102:  );
103:  /** How many of the sheet's claims have each status. */
104:  protected readonly statusCounts = computed(() => {
105:    const by = new Map<string, number>();
106:    for (const c of this.claims()) by.set(c.status, (by.get(c.status) ?? 0) + 1);
107:    return by;
108:  });
109:  /** How many of the sheet's claims that count are overdue, and the sum of their dues (n/a ones skipped). */
110:  protected readonly overdueCount = computed(() =>
111:    this.people().reduce((n, p) => n + this.overdueOf(p).length, 0),
112:  );
113:  protected readonly overdueTotal = computed(() => sumAmounts(this.people().map((p) => this.overdueTotalOf(p))));
114:  protected readonly editingId = signal<number | null>(null);
115:  /** The version of the person the editor loaded. */
116:  private editingVersion: number | null = null;
117:  /** Whether a submit is waiting on the server; another submit is ignored until it answers. */
118:  private submitting = false;
119:  protected readonly formError = signal<string | null>(null);
120:  /** The error of the last action taken on a person's row, shown on that row. */
121:  protected readonly personError = signal<{ id: number; message: string } | null>(null);
122:  /** The error of the last patron added on a person's row, shown on that row. */
123:  protected readonly patronError = signal<{ id: number; message: string } | null>(null);
124:  protected readonly form = new FormGroup({
125:    name: new FormControl('', { nonNullable: true }),
126:    grade: new FormControl<Grade>('A', { nonNullable: true }),
127:    /** The date a saved grade is in force from; the sheet's today unless another date is picked. */
128:    gradeFrom: new FormControl('', { nonNullable: true }),
129:  });
130:
131:  /** Whether a quick-add is waiting on the server; another is ignored until it answers. */
132:  private quickAdding = false;
133:  protected readonly quickError = signal<string | null>(null);
134:  protected readonly quickForm = new FormGroup({
135:    name: new FormControl('', { nonNullable: true }),
136:    amount: new FormControl('', { nonNullable: true }),
137:  });
138:
139:  constructor() {
140:    this.form.valueChanges.subscribe(() => this.formError.set(null));
141:    this.quickForm.valueChanges.subscribe(() => this.quickError.set(null));
142:    effect(() => {
143:      const today = this.session.today() ?? '';
144:      untracked(() => {
145:        if (!this.form.controls.gradeFrom.dirty) this.form.controls.gradeFrom.setValue(today, { emitEvent: false });
146:      });
147:    });
148:    // Re-read the sheet's people and their claims from the store each time a sheet is loaded.
149:    const loaded = this.session.registerLoader(inject(DestroyRef));
150:    toObservable(this.session.sheetId)
151:      .pipe(
152:        switchMap((id) =>
153:          id
154:            ? forkJoin({
155:                id: of(id),
156:                people: this.api.list(id),
157:                claims: this.claimsApi.list(id),
158:                rates: this.ratesApi.list(id),
159:                periods: this.periodsApi.list(id),
160:              })
161:            : of({ id, people: [] as Person[], claims: [] as Claim[], rates: [] as Rate[], periods: [] as Period[] }),
162:        ),
163:      )
164:      .subscribe(({ id, people, claims, rates, periods }) => {
165:        this.people.set(people);
166:        this.periods.set(periods);
167:        this.claims.set(claims);
168:        this.rates.set(rates);
169:        this.reset();
170:        loaded(id);
171:      });
172:  }
173:
174:  protected claimsOf(personId: number): Claim[] {
175:    return this.claimsByPerson().get(personId) ?? [];
176:  }
177:
178:  protected claimed(personId: number): string {
179:    return sumAmounts(this.claimsOf(personId).filter((c) => this.countsLive(c)).map((c) => c.amount));
180:  }
181:
182:  /** The grade the person has in force on the sheet's today. */
183:  protected gradeToday(person: Person): Grade {
184:    const today = this.session.today();
185:    return (today !== null ? gradeOn(person.grades, today) : undefined) ?? person.grade;
186:  }
187:
188:  /** What is due on a claim of the person's, at the grade they have on the claim's date. */
189:  private claimDue(claim: Claim, person: Person): string {
190:    return claimDue(claim, this.rates(), gradeOn(person.grades, claim.date), this.floor.value(), this.late(),
191:      roundsBy(claim, this.claimsOf(person.id)));
192:  }
193:
194:  /** The sum of the dues of the claims the person has that count (n/a ones skipped), 0.00 with none. A
195:   * person shows n/a when neither the grade they have on the sheet's today nor one they had on the date of a
196:   * claim that counts has a rate in force on the sheet's today, unless a settled or stated claim keeps a
197:   * figure. */
198:  protected personDueTotal(person: Person): string {
199:    const counted = this.claimsOf(person.id).filter((c) => this.countsLive(c));
200:    const frozen = counted.some(keepsFigure);
201:    const grades = [this.gradeToday(person), ...counted.map((c) => gradeOn(person.grades, c.date))];
202:    if (!grades.some((g) => g !== undefined && this.rateByGrade().has(g)) && !frozen) return NO_RATE;
203:    return sumAmounts(counted.map((c) => this.claimDue(c, person)).filter((d) => d !== NO_RATE));
204:  }
205:
206:  /** The person's claims that count and are overdue. */
207:  protected overdueOf(person: Person): Claim[] {
208:    const today = this.session.today();
209:    return this.claimsOf(person.id).filter((c) => this.countsLive(c) && isOverdue(c, this.terms.value(), today));
210:  }
211:
212:  /** The sum of the dues of the person's overdue claims that count (n/a ones skipped), 0.00 with none. */
